function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 30000) return 'nums needs 2 to 3 * 10^4 values.';
  if (!nums.every(v => Number.isInteger(v) && v >= -2147483648 && v <= 2147483647)) return 'Each value is a 32-bit signed integer.';
  const counts = new Map();
  for (const value of nums) counts.set(value, (counts.get(value) || 0) + 1);
  let singles = 0;
  for (const count of counts.values()) {
    if (count === 1) singles++;
    else if (count !== 2) return 'Every value other than the two singles must appear exactly twice.';
  }
  if (singles !== 2) return 'Exactly two values must appear only once.';
  return null;
}

