function generate(rand, size) {
  const MIN = -2147483648, MAX = 2147483647;
  const pairCount = size === 'large' ? 999 : Math.floor(rand() * 4);
  const used = new Set();
  const fresh = () => {
    for (;;) {
      let value;
      if (size === 'large') value = MIN + Math.floor(rand() * 4294967296);
      else {
        const roll = rand();
        value = roll < 0.1 ? MIN : roll < 0.2 ? MAX : Math.floor(rand() * 11) - 5;
      }
      if (!used.has(value)) {
        used.add(value);
        return value;
      }
    }
  };
  const nums = [fresh(), fresh()];
  for (let p = 0; p < pairCount; p++) {
    const value = fresh();
    nums.push(value, value);
  }
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
